async function animatePosterBooking(movie,event,go,lock){
 if(lock.current)return;
 const button=event?.currentTarget;
 const source=button?.closest('.reel-card')?.querySelector('.reel-poster img')||button?.closest('.moviecard')?.querySelector('.poster img')||button?.closest('.detailhero')?.querySelector('img');
 let didRoute=false;const route=()=>{if(didRoute)return;didRoute=true;sessionStorage.setItem('showtimeReturnMovie',String(movie.id));go(`select/${movie.id}`)};
 if(!source||!movie.poster||matchMedia('(prefers-reduced-motion: reduce)').matches){route();return}
 const rect=source.getBoundingClientRect();
 if(!rect.width||!rect.height){route();return}
 lock.current=true;
 let shade,image,routeTimer;
 try{
  shade=document.createElement('div');shade.className='book-transition-shade';shade.setAttribute('aria-hidden','true');
  image=source.cloneNode();image.className='book-poster-flight';image.alt='';image.setAttribute('aria-hidden','true');image.src=source.currentSrc||movie.poster;
  Object.assign(image.style,{left:`${rect.left}px`,top:`${rect.top}px`,width:`${rect.width}px`,height:`${rect.height}px`});
  document.body.append(shade,image);
  const dx=innerWidth/2-(rect.left+rect.width/2),dy=innerHeight/2-(rect.top+rect.height/2);
  const zoom=Math.max(innerWidth/rect.width,innerHeight/rect.height)*1.035;
  const finalTransform=`translate3d(${dx}px,${dy}px,0) scale(${zoom})`;
  const flight=image.animate([
   {transform:'translate3d(0,0,0) scale(1)'},
   {transform:finalTransform}
  ],{duration:900,easing:'cubic-bezier(.65,0,.35,1)',fill:'forwards'});
  const dim=shade.animate([{opacity:0},{opacity:.38}],{duration:900,easing:'cubic-bezier(.65,0,.35,1)',fill:'forwards'});
  // Begin rendering the destination while the poster is still in motion, so the zoom never waits on React.
  await new Promise(resolve=>{routeTimer=setTimeout(()=>{route();resolve()},680)});
  await Promise.all([flight.finished,dim.finished]);
  await new Promise(requestAnimationFrame);
  const content=document.querySelector('.content');
  const arrival=content?.animate([
   {opacity:0,transform:'translateY(8px) scale(.996)'},
   {opacity:1,transform:'translateY(0) scale(1)'}
  ],{duration:420,easing:'cubic-bezier(.65,0,.35,1)',fill:'both'});
  const reveal=image.animate([{opacity:1,transform:finalTransform},{opacity:0,transform:finalTransform}],{duration:300,easing:'linear',fill:'forwards'});
  const fadeShade=shade.animate([{opacity:.38},{opacity:0}],{duration:300,easing:'linear',fill:'forwards'});
  await Promise.all([reveal.finished,fadeShade.finished,arrival?.finished||Promise.resolve()]);
 }catch(error){route()}finally{clearTimeout(routeTimer);shade?.remove();image?.remove();lock.current=false}
}


