  const dim=shade.animate([{opacity:0},{opacity:.3}],{duration:760,easing:'cubic-bezier(.65,0,.35,1)',fill:'forwards'});
  await new Promise(resolve=>{routeTimer=setTimeout(()=>{route();requestAnimationFrame(()=>{app.animate([{opacity:0,transform:'scale(.985)'},{opacity:1,transform:'scale(1)'}],{duration:360,easing:'cubic-bezier(.65,0,.35,1)'});app.style.opacity='1';resolve()})},440)});
  await Promise.all([flight.finished,dim.finished]);
